import * as dotenv from 'dotenv';
dotenv.config({ override: true });

import { createHash } from 'crypto';
import { createClient } from '@supabase/supabase-js';
import { fetchKulturhusetEvents } from './src/sources/kulturhuset.js';

const supabase = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);

function buildDedupHash(source, sourceId) {
  return createHash('sha256').update(`${source}::${sourceId}`).digest('hex');
}

async function insertKulturhusetEvents() {
  console.log('Fetching Kulturhuset events...');
  const events = await fetchKulturhusetEvents({ limit: 10 });
  console.log(`Got ${events.length} events`);

  let inserted = 0;
  let updated = 0;
  let errors = 0;

  for (const event of events) {
    const dedupHash = buildDedupHash('kulturhuset', event.id);

    // Check if exists
    const { data: existing } = await supabase
      .from('events')
      .select('id')
      .eq('dedup_hash', dedupHash)
      .single();

    if (existing) {
      // Update existing
      const { error } = await supabase
        .from('events')
        .update({
          title_en: event.title,
          description_en: event.description,
          start_time: event.date + 'T' + (event.time || '00:00:00'),
          source: 'kulturhuset',
          source_id: event.id,
          category_slug: event.category,
          status: 'published',
          updated_at: new Date().toISOString(),
        })
        .eq('id', existing.id);

      if (error) {
        console.error(`Error updating ${event.id}:`, error.message);
        errors++;
      } else {
        updated++;
      }
    } else {
      // Insert new
      const { error } = await supabase
        .from('events')
        .insert({
          title_en: event.title,
          description_en: event.description,
          start_time: event.date + 'T' + (event.time || '00:00:00'),
          source: 'kulturhuset',
          source_id: event.id,
          category_slug: event.category,
          status: 'published',
          dedup_hash: dedupHash,
          venue_id: null, // Will be resolved by normalizer
          lat: 59.3293,
          lng: 18.0686,
        });

      if (error) {
        console.error(`Error inserting ${event.id}:`, error.message);
        errors++;
      } else {
        inserted++;
      }
    }
  }

  console.log(`\n✅ Inserted: ${inserted}, Updated: ${updated}, Errors: ${errors}`);
  return { inserted, updated, errors };
}

async function verifyEvents() {
  console.log('\nVerifying events in Supabase...');

  const { count } = await supabase
    .from('events')
    .select('id', { count: 'exact', head: true })
    .eq('source', 'kulturhuset')
    .eq('status', 'published');

  console.log(`Kulturhuset events in DB: ${count}`);

  const { data: events } = await supabase
    .from('events')
    .select('id, title_en, start_time')
    .eq('source', 'kulturhuset')
    .eq('status', 'published')
    .limit(5);

  console.log('\nSample events:');
  events?.forEach(e => console.log(`  - ${e.title_en} (${e.start_time})`));
}

async function main() {
  try {
    await insertKulturhusetEvents();
    await verifyEvents();
  } catch (error) {
    console.error('Fatal error:', error.message);
  }
}

main();
EOF
node test_kh_direct.mjs

